// An object stores related data as key: value pairs
const student = {
  name: "Ayesha",
  age: 20,
  courses: ["HTML", "CSS", "JavaScript"],
  address: { city: "Lahore", country: "Pakistan" },
  greet() {
    return "Hi, I am " + this.name;
  },
};

console.log(student.name);            // dot notation
console.log(student["age"]);          // bracket notation
console.log(student.address.city);    // nested object
console.log(student.greet());         // method

student.age = 21;                     // change a value
student.email = "ayesha@example.com"; // add a property
delete student.address;               // remove a property

console.log(Object.keys(student));
for (const [key, value] of Object.entries(student)) {
  if (typeof value !== "function") console.log(key + " =>", value);
}

