sayHi();                 // function declarations are fully hoisted
function sayHi() {
  console.log("Hi!");
}

function makeCounter() {
  let count = 0;                 // private variable
  return function () {
    count++;
    return count;
  };
}

const counterA = makeCounter();
const counterB = makeCounter();

console.log(counterA());   // 1
console.log(counterA());   // 2
console.log(counterB());   // 1  (its own separate count)

// Classic loop problem: var shares ONE variable, let makes a new one each round
const withVar = [];
for (var i = 0; i < 3; i++) withVar.push(() => i);
const withLet = [];
for (let j = 0; j < 3; j++) withLet.push(() => j);

console.log(withVar.map((fn) => fn()));  // [3, 3, 3]
console.log(withLet.map((fn) => fn()));  // [0, 1, 2]

const name = "Hira";
const score = 87;

// 1. Template literals: backticks + ${ }
console.log(`${name} scored ${score}/100 (${score >= 50 ? "pass" : "fail"})`);

