const { username, role } = user;
const [first, , third] = ["a", "b", "c"];
console.log(username, role, first, third);

// 4. Spread and rest
const nums = [1, 2, 3];
const more = [...nums, 4, 5];
const merged = { ...user, role: "teacher" };
const sum = (...values) => values.reduce((total, v) => total + v, 0);
console.log(more, merged.role, sum(1, 2, 3, 4));

// 5. Shorthand properties
