const person = { name, age };
console.log(person);

function parseUser(text) {
  try {
    const user = JSON.parse(text);
    if (!user.name) throw new Error("User must have a name");
    return user;
  } catch (error) {
    console.log("Problem: " + error.message);
    return null;
  } finally {
    console.log("Finished parsing");   // always runs
  }
}

console.log(parseUser('{"name": "Sara"}'));
console.log(parseUser('{"age": 20}'));
console.log(parseUser("not json at all"));

class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function validateAge(age) {
  if (typeof age !== "number") throw new ValidationError("age", "Age must be a number");
  if (age < 0 || age > 120) throw new ValidationError("age", "Age must be between 0 and 120");
  return age;
}

for (const input of [25, -5, "abc"]) {
  try {
    console.log("OK:", validateAge(input));
  } catch (e) {
    if (e instanceof ValidationError) console.log(`${e.name} on "${e.field}": ${e.message}`);
    else throw e;   // not ours, do not hide it
  }
}

